from pathlib import Path
import re,json
source=Path('docs/end-to-end-test-checklist.md').read_text()
groups=[];current=None
for line in source.splitlines():
    if line.startswith('## '):
        title=line[3:]
        if re.match(r'^\d+\.',title) or title=='Completion criteria':
            current={'title':title,'items':[]};groups.append(current)
        else:current=None
    match=re.match(r'- \[([ x])\] (?:(\w+-\d+): )?(.*)',line)
    if match and current:
        done=match[1]=='x';code=match[2] or f"SIGN-{len(current['items'])+1:02d}"
        status='passed' if done else 'pending'
        note=''
        if code in ['ACC-01','ACC-05','ACC-06','ACC-10']:note='User-confirmed browser pass, supported by earlier automated/API checks.'
        if code.startswith(('CAT-','INV-')) and done:note='Passed at the browser/API/automated layers recorded in the 27 October module report.'
        if code=='INV-02':note='Passed in the browser on 28 October with a controlled simulated payment: exact store stock 50 → 48 → 50 after cancellation. No provider payment inferred.'
        if code in ['ORD-06','ORD-14']:status='blocked';note='Real integration remains blocked as recorded in the latest module report; simulated callbacks/retries do not establish provider completion.'
        if code=='INV-08':status='blocked';note='Real POS test blocked at your request. Mapping/retry/downtime simulations pass; no real test POS endpoint is connected.'
        if code.startswith('SET-') and done:note='Setup preparation verified on 28 October. Evidence is in the setup completion report; later module workflows remain separate.'
        if code.startswith('SET-') and not done:note='Setup checklist remains unchecked; some preparation exists, but the full scenario has not been signed off.'
        if code.startswith(('CON-', 'PED-')) and done:note='Passed at the recorded API/browser/automated layers; genuine doctor and pediatric STK reruns are documented in the 1 November connected-journey evidence.'
        if code.startswith('LAB-') and done:note='Passed at the browser/API/automated layers recorded in the 30 October lab report. Pay-later booking; no online lab payment offered or inferred.'
        if code=='E2E-05' and done:note='Local synthetic lab journey passed with documented browser/API/automated coverage. Notification creation verified; external delivery not independently confirmed.'
        if code.startswith('PAY-') and done:note='Passed at recorded local browser/API/automated layers. Administrative ledger only; no bank or M-Pesa transfer was sent. See the 30 October payout report.'
        if code.startswith(('NOT-', 'SUP-')) and done:note='Passed at the browser/API/automated layers in the 30 October notifications/support report. External mailbox/SMS receipt and hosted deployment are not independently confirmed.'
        if code=='CON-04' and done:note='Genuine KSh 1 doctor payment confirmed: receipt UK1I20IYUB, consultation CONS-83F95C. Earlier failed attempts remain historical.'
        if code=='PED-02':status='passed';note='Provider-confirmed KSh 1 receipt UJUI207MTB / intent 51; CONS-8AF578 completed for the correct child/guardian with one KSh 0.90 earning. Earlier intent 50 is tracked separately.'
        current['items'].append(dict(id=code,text=match[3],status=status,note=note))
data=json.dumps(groups).replace('<','\\u003c')
html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ava Pharmacy · QA checklist</title>
<style>
:root{font-family:Inter,system-ui,sans-serif;color:#1b302c;background:#f5f8f7;font-size:15px}*{box-sizing:border-box}body{margin:0}header{background:#fff;border-bottom:1px solid #dfe8e4;padding:28px max(24px,calc((100vw - 1180px)/2))}header .brand{color:#22775e;font-weight:750;letter-spacing:.03em;font-size:13px}h1{font-size:30px;letter-spacing:-.035em;margin:12px 0 8px}p{line-height:1.55;margin:7px 0;color:#54665e}main{max-width:1228px;margin:auto;padding:24px} .stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:22px}.stat{background:white;border:1px solid #dfe8e4;border-radius:14px;padding:18px}.stat b{font-size:29px;display:block;margin-top:7px}.stat span{font-size:13px;color:#54665e}.green b{color:#187652}.amber b{color:#996319}.layout{display:grid;grid-template-columns:260px minmax(0,1fr);gap:24px}nav{align-self:start;position:sticky;top:20px;background:#fff;border:1px solid #dfe8e4;border-radius:14px;padding:12px}nav button{border:0;background:none;padding:12px;width:100%;display:flex;justify-content:space-between;gap:10px;text-align:left;border-radius:8px;color:#42594f;font:inherit;font-size:13px;cursor:pointer}nav button.active{background:#e6f3ec;color:#14553f;font-weight:650}nav small{white-space:nowrap;color:#66796e}.controls{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:18px;position:sticky;top:0;background:#f5f8f7;padding:8px 0;z-index:1}input,select,button{font:inherit}input,select{border:1px solid #d4e0da;background:white;border-radius:9px;padding:11px 12px}input{flex:1;min-width:180px}button.print{border:1px solid #d4e0da;background:white;border-radius:9px;padding:10px;cursor:pointer}.section{margin-bottom:22px;background:#fff;border:1px solid #dfe8e4;border-radius:14px;overflow:hidden}.section-head{padding:20px;border-bottom:1px solid #e7eeea}.section-head h2{font-size:18px;margin:0 0 9px}.section-head small{color:#617568}.bar{height:5px;background:#edf2ef;border-radius:9px;margin-top:12px;overflow:hidden}.bar span{display:block;height:100%;background:#3d9e78}.row{display:grid;grid-template-columns:23px minmax(0,1fr) auto;gap:12px;padding:17px 20px;border-bottom:1px solid #edf1ee}.row:last-child{border:0}.box{height:20px;width:20px;border:1.6px solid #bdcbc3;border-radius:5px;display:grid;place-items:center;font-size:14px;margin-top:1px;color:white}.passed .box{background:#25815b;border-color:#25815b}.blocked .box{border-color:#bd862f;color:#966011;background:#fff5df}.id{font-size:11px;font-weight:750;color:#73847b;letter-spacing:.04em;display:block;margin-bottom:5px}.description{line-height:1.5;font-size:14px}.note{font-size:12px;color:#64786b;margin-top:7px;line-height:1.5}.badge{font-size:11px;border-radius:20px;padding:5px 8px;white-space:nowrap;align-self:start;background:#eff2f0;color:#607166}.passed .badge{background:#e5f4eb;color:#1c704a}.blocked .badge{background:#fff1d3;color:#885b16}.empty{text-align:center;padding:40px;color:#65786e}.foot{font-size:12px;margin-top:20px}.callout{border-left:3px solid #c8953e;padding:7px 13px;margin-top:14px;background:#fffbf1;font-size:13px;color:#715c32}.tag{font-size:12px;color:#64786b} @media(max-width:760px){.layout{grid-template-columns:1fr}nav{position:static;display:flex;overflow:auto}nav button{min-width:170px}.stats{grid-template-columns:repeat(2,1fr)}.row{grid-template-columns:20px minmax(0,1fr)}.badge{grid-column:2;justify-self:start}h1{font-size:25px}}@media print{nav,.controls{display:none}.layout{display:block}.section{break-inside:auto}.row{break-inside:avoid}header{padding:20px}main{padding:0}.stats{margin:20px 0}body{background:white}}
</style></head><body><header><div class="brand">AVA PHARMACY / QUALITY ASSURANCE</div><h1>End-to-end testing checklist</h1><p>See what has passed, what remains unchecked, and what is blocked.</p><div class="tag">Updated 1 November 2026 · Reconciled with documented test results</div><div class="callout">Completion review: 3 of 6 criteria complete. E2E-01–05 pass at documented layers; E2E-06 awaits an actual external refund and live support closure. Genuine STK doctor and pediatric payments are confirmed. Paybill, real POS, older pediatric intent reconciliation, external delivery verification and hosted deployment remain explicit boundaries. Human reviewer sign-off is pending.</div></header><main><div class="stats" id="stats"></div><div class="layout"><nav id="modules" aria-label="Filter by module"></nav><div><div class="controls"><input id="search" aria-label="Search checklist" placeholder="Search a check, module or scenario ID…"><select id="status" aria-label="Filter by status"><option value="all">All statuses</option><option value="passed">Checked / passed</option><option value="pending">Unchecked / pending</option><option value="blocked">Blocked</option></select><button class="print" onclick="window.print()">Print / Save PDF</button></div><div id="results" aria-live="polite"></div><p class="foot">Read-only status view generated from docs/end-to-end-test-checklist.md. Pending means the full checklist scenario is not signed off; supporting tests may already exist. Status changes belong in the source checklist and test reports.</p></div></div></main><script>
const groups=__DATA__; let selected='all';
const all=groups.flatMap(g=>g.items), count=s=>all.filter(i=>i.status===s).length;
const esc=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
document.getElementById('stats').innerHTML=[['Total checks',all.length,''],['Checked / passed',count('passed'),'green'],['Unchecked / pending',count('pending'),''],['Blocked',count('blocked'),'amber']].map(([a,b,c])=>`<div class="stat ${c}"><span>${a}</span><b>${b}</b></div>`).join('');
function render(){const q=document.getElementById('search').value.toLowerCase(),status=document.getElementById('status').value;document.getElementById('modules').innerHTML=[{title:'All modules',items:all},...groups].map(g=>{let id=g.title==='All modules'?'all':g.title;return `<button class="${selected===id?'active':''}" data-module="${esc(id)}"><span>${esc(g.title)}</span><small>${g.items.filter(i=>i.status==='passed').length}/${g.items.length}</small></button>`}).join('');document.querySelectorAll('[data-module]').forEach(b=>b.onclick=()=>{selected=b.dataset.module;render()});let html='';for(const g of groups){if(selected!=='all'&&selected!==g.title)continue;const visible=g.items.filter(i=>(status==='all'||i.status===status)&&`${g.title} ${i.id} ${i.text} ${i.note}`.toLowerCase().includes(q));if(!visible.length)continue;const passed=g.items.filter(i=>i.status==='passed').length;html+=`<section class="section"><div class="section-head"><h2>${esc(g.title)}</h2><small>${passed} of ${g.items.length} checked${g.items.some(i=>i.status==='blocked')?' · blocked checks remain':''}</small><div class="bar"><span style="width:${100*passed/g.items.length}%"></span></div></div>${visible.map(i=>`<div class="row ${i.status}"><span class="box" role="img" aria-label="${i.status==='passed'?'Checked':'Unchecked'}">${i.status==='passed'?'✓':i.status==='blocked'?'!':''}</span><div><span class="id">${esc(i.id)}</span><div class="description">${esc(i.text)}</div>${i.note?`<div class="note">${esc(i.note)}</div>`:''}</div><span class="badge">${i.status==='passed'?'Passed':i.status==='blocked'?'Blocked':'Pending'}</span></div>`).join('')}</section>`}document.getElementById('results').innerHTML=html||'<div class="empty">No checks match these filters.</div>'}
document.getElementById('search').oninput=render;document.getElementById('status').onchange=render;render();
</script></body></html>'''.replace('__DATA__',data)
Path('output/qa-checklist/index.html').write_text(html)
print(json.dumps({'total':sum(len(g['items']) for g in groups),'passed':sum(i['status']=='passed' for g in groups for i in g['items']),'blocked':sum(i['status']=='blocked' for g in groups for i in g['items']),'modules':len(groups)}))
